"""Reader keys for the protocol (Table S9) and study assessments (Table S8); canonical rules remain in the Markdown master."""
S2_NOTE = ('Use this instrument to identify the record unit, decide applicability, then select a response and record its evidence. '
           'The author performed the final review of all screening, extraction and appraisal decisions against the source reports. '
           'The key below explains shared terms; item rows give the individual rules. Exact codes and full records are in the S9 workbook and S7.')
S2_KEYS = [
 ('Reporting prevalence', 'Figure 9 counts at least one evaluated unit: explicit THR01 method, IMB05 full recovery, positive integer VAL10, or IMB04 original prevalence. Independent selection requires positive THR01 and THR03 in the same registered evaluation with compatible links; denominator: threshold-reporting studies. Positive precedes unclear, then NR, then wholly NA; mixed raw records remain in S7.'),
 ('States and tokens', 'NR: applicable but not reported. NA: structurally inapplicable. UNCLEAR: insufficient/conflicting evidence (historical UNC, including REP01–19). Numeric/text values require a separate status. Official PROBAST NI is unchanged.'),
 ('Units and linkage', 'Keep repeated outcomes, models, developments and evaluations separate. Purpose/output/use/stage IDs identify records, not statistical analyses. NO_SPECIFIC_USE is derived, not a USE01 input.'),
 ('Recovery and reporting', 'OUT16/PRD13 assess outcome/input recovery; their study summaries use the least recoverable observed outcome/model. REP06/07 assess study-level reporting. These are distinct constructs; OUT16 also requires source and timing.'),
 ('Credibility and alignment', 'OUT17 assesses outcome-definition support; PRD14 assesses predictor availability/alignment. Explicit leakage/circularity/misalignment takes precedence over favourable basis in the affected construct. C1 is limited support; CU is unassessable. These review-defined grades are not PROBAST categories.'),
 ('Evidence support', 'Individual-use support counts validation, calibration and threshold within a study, without same-model/outcome/evaluation linkage or independent threshold selection. Policy support requires weights plus a design feature within a study; association support requires analysis-level linkage. These are review-defined, nonvalidated summaries.'),
 ('Historical grades', 'Current definitions clarify use of the instrument; they do not retrospectively certify retained grades or explain every discordance. Original responses and rationales remain in S7; known boundary examples are described in the canonical Reader guide.'),
 ('Appraisal reference', 'Moons et al., BMJ 2025;388:e082505 (doi:10.1136/bmj-2024-082505): the article’s Table S3 is the official PROBAST+AI tool and Table S4 is E&E Light, distinct from this review’s S3/S4. Access: https://www.probast.org/probast_ai/downloads/ or https://pmc.ncbi.nlm.nih.gov/articles/PMC11931409/ .'),
]
S9_NOTE = ('Panels A–C show the recorded assessments for all 220 included studies; panel D compares recovery and reporting in the 165-study core cohort. '
           'Read counts with their named units and the key below. S7 contains the full responses, citations and source evidence.')
S9_KEYS = [
 ('Counts and units', 'Outcome/model/development/evaluation counts use unique registered unit IDs; otherwise the table says response records. Counts include NA and are not applicable-unit denominators. Cohort n counts participants, not evaluation units.'),
 ('States', 'NR: not reported after review; NA: not applicable; UNC/UNCLEAR: unresolved; null/no record: not extracted. USED/NOT_USED retain the recorded method-use judgement.'),
 ('Recovery and reporting', 'R2/R1/R0: fully/partly/not recoverable outcome or input set, not whole-analysis reproducibility. Panel D compares least-recoverable outcome/model summaries with study-level reporting; each construct totals 165 studies. OUT16 also requires source and timing. Differences do not automatically indicate coding errors.'),
 ('Appraisal direction', 'Development HIGH/LOW means high/low quality; evaluation HIGH/LOW means high/low bias risk. Current clarifications do not retrospectively adjudicate retained grades.'),
 ('Support states and scope', 'Y: criterion documented as met. N: criterion not documented as met; it cannot distinguish nonuse, nonreporting and unresolved evidence. Each flag has its own eligible set: importance outputs, association purposes, individual-use claims or policy uses; NA is outside that set.'),
 ('Support criteria', 'Importance requires stability assessment. Association requires weights and design-based uncertainty linked to the same analysis. Individual use counts validation, calibration and threshold within a study without same-model/outcome/evaluation linkage; independent threshold selection is not required. Policy requires weights plus a design feature within a study. These review-defined summaries are not a validated global score.'),
 ('Evidence and scope caveat', 'Tagged example evidence IDs locate items, not proof of every row field. S7 retains all values, statuses, units and source references. KHM068 is retained for corpus/appraisal history; its performance is excluded from substantive evidence.'),
]
